using JointLocalNormProbeClassifierV1=bool(*)(const void*);
extern "C" __declspec(dllimport) JointLocalNormProbeClassifierV1 RinkfitCeresSetLocalNormProbeClassifierV1(JointLocalNormProbeClassifierV1);
class JointOpticalNormProbeScopeV1 {
 JointLocalNormProbeClassifierV1 previous_=nullptr;bool active_=false;
 static bool local(const void*p){const auto*m=joint_solver_original_manifold_v1(static_cast<const ceres::Manifold*>(p));return dynamic_cast<const JointOpticalDomainFaceManifoldV1*>(m)!=nullptr;}
 public:explicit JointOpticalNormProbeScopeV1(bool active):active_(active){if(active_)previous_=RinkfitCeresSetLocalNormProbeClassifierV1(local);}~JointOpticalNormProbeScopeV1(){if(active_)RinkfitCeresSetLocalNormProbeClassifierV1(previous_);}JointOpticalNormProbeScopeV1(const JointOpticalNormProbeScopeV1&)=delete;
};
// Reversible active set for the original closed lens certificates. A face is
// entered only after real one-coordinate objective descent reaches its actual
// boundary, or the saved point is already that boundary. No near-face cutoff.
class JointOpticalWorkingSetV1 {
 struct Held{double*x;const ceres::Manifold*original;std::array<double,6>lo,hi;const JointRig*rig;const JointOpticalDomainFaceManifoldV1*face;};
 std::vector<Held>held_;std::vector<ceres::ResidualBlockId>connected_;
 struct Raw{long double gradient=0,H=0,cost=0;std::vector<long double>factor_cost;};
 static long double loss_cost(const ceres::LossFunction*loss,const std::vector<double>&r,double*rho1=nullptr,double*rho2=nullptr){long double s=0;for(double v:r){if(!std::isfinite(v))throw std::runtime_error("optical actual residual nonfinite");s+=(long double)v*v;}double rho[3]={double(s),1.,0.};if(loss)loss->Evaluate(double(s),rho);if(!std::isfinite(rho[0])||!std::isfinite(rho[1])||!std::isfinite(rho[2]))throw std::runtime_error("optical actual loss nonfinite");if(rho1)*rho1=rho[1];if(rho2)*rho2=rho[2];return loss?.5L*rho[0]:.5L*s;}
 Raw actual(ceres::Problem&p,double*x,bool jacobian,bool keep_costs){Raw out;std::vector<double*>pars;std::vector<const double*>cp;std::vector<double>r,j;std::vector<double*>jp;for(auto rid:connected_){p.GetParameterBlocksForResidualBlock(rid,&pars);const auto*cost=p.GetCostFunctionForResidualBlock(rid);const auto*loss=p.GetLossFunctionForResidualBlock(rid);const auto&sizes=cost->parameter_block_sizes();const auto found=std::find(pars.begin(),pars.end(),x);if(found==pars.end())throw std::runtime_error("optical incidence omits actual block");const auto slot=std::size_t(found-pars.begin());if(sizes.at(slot)!=12)throw std::runtime_error("optical ambient size changed");r.resize(cost->num_residuals());cp.assign(pars.begin(),pars.end());jp.assign(pars.size(),nullptr);if(jacobian){j.resize(std::size_t(r.size())*12);jp[slot]=j.data();}if(!cost->Evaluate(cp.data(),r.data(),jacobian?jp.data():nullptr))throw std::runtime_error("optical actual associated factor evaluation failed");double rho1=1,rho2=0;const long double value=loss_cost(loss,r,&rho1,&rho2);out.cost+=value;if(keep_costs)out.factor_cost.push_back(value);if(!jacobian)continue;long double g=0,H=0,s=0;for(std::size_t a=0;a<r.size();++a){const double d=j[a*12+5];if(!std::isfinite(d))throw std::runtime_error("optical raw dependent derivative missing/nonfinite");g+=(long double)r[a]*d;H+=(long double)d*d;s+=(long double)r[a]*r[a];}out.gradient+=rho1*g;long double corrected=rho1*H;if(rho1>0&&rho2>0&&s>0){const long double alpha=1-std::sqrt(1+2*s*rho2/rho1);corrected+=rho1*(alpha*alpha-2*alpha)*g*g/s;}out.H+=corrected;}return out;}
 template<class Builder>void ready(Builder&b,bool new_point=false){if(auto*c=b.gpu_evaluation_callback())c->PrepareForEvaluation(true,new_point);}
 public:
 using Signature=std::set<std::pair<std::string,int>>;Signature signature;bool primal_changed=false;
 class ScopeRestoreV1{JointOpticalWorkingSetV1*self_;ceres::Problem*p_;public:ScopeRestoreV1(JointOpticalWorkingSetV1*s,ceres::Problem*p):self_(s),p_(p){}~ScopeRestoreV1(){if(self_)self_->restore(*p_);}void release(){self_=nullptr;}ScopeRestoreV1(const ScopeRestoreV1&)=delete;};
 bool active()const{return !held_.empty();}
 void restore(ceres::Problem&p){for(const auto&h:held_){p.SetManifold(h.x,const_cast<ceres::Manifold*>(h.original));for(int a=5;a<=10;++a){p.SetParameterLowerBound(h.x,a,h.lo[a-5]);p.SetParameterUpperBound(h.x,a,h.hi[a-5]);}}held_.clear();}
 template<class Builder>eventio::Json prepare(Builder&b,ceres::Problem&p,const JointCaptureCertifiedDomainV1&domain){
  if(!held_.empty())throw std::runtime_error("optical working set prepare before restore");signature.clear();primal_changed=false;eventio::Json rows=eventio::Json::array();try{ready(b);for(const auto&rig:b.core.model.rigs){auto&block=b.core.model.blocks.at(rig.optics_block);auto*x=block.values.data();if(!p.HasParameterBlock(x)||p.IsParameterBlockConstant(x))continue;const auto*original=p.GetManifold(x);if(dynamic_cast<const JointSolverMetricManifoldV1*>(original))throw std::runtime_error("optical face must precede metric");const int k=p.ParameterBlockTangentSize(x);std::vector<double>A(12*k,0.);if(original){if(!original->PlusJacobian(x,A.data()))throw std::runtime_error("optical original face Jacobian failed");}else for(int a=0;a<12;++a)A[a*k+a]=1.;bool free=false;for(int c=0;c<k;++c)if(A[5*k+c]!=0){bool only=true;for(int a=0;a<12;++a)if(a!=5&&A[a*k+c]!=0)only=false;free=free||only;}if(!free)continue;
   std::array<JointZoomCertificate,2>tests;const auto range=domain.ranges.at(rig.id);for(int e=0;e<2;++e){auto&c=tests[e];c.f_ref=rig.math.f_ref;c.radius=rig.math.radius_max;c.endpoint=e;c.wide_boundary=rig.math.wide_log_f_boundary;c.wide_coefficients=rig.math.wide_coefficients;}
   auto gates=[&](double value,std::array<double,2>*values=nullptr){const double saved=x[5];x[5]=value;const double*pars[]={x,range.data()};bool valid=std::isfinite(value)&&value>=block.lower[5]&&value<=block.upper[5];for(int e=0;e<2;++e){double g=NAN;const bool evaluated=tests[e](pars,&g)&&std::isfinite(g);if(values)(*values)[e]=g;valid=valid&&evaluated&&g<=0;}x[5]=saved;return valid;};
   if(!gates(x[5]))throw std::runtime_error("optical active set base is outside original closed certificate");connected_.clear();p.GetResidualBlocksForParameterBlock(x,&connected_);const auto base=actual(p,x,true,true);const double G=double(base.gradient),H=double(base.H);const double tol=128*std::numeric_limits<double>::epsilon()*std::max(1.,std::abs(G));eventio::Json row={{"rig",rig.id},{"dependent_ambient_index",5},{"actual_complete_factor_JTr",G},{"associated_residual_blocks",connected_.size()},{"not_a_multiplier_before_face_convergence",true},{"active",false}};
   if(!(G>tol)||!(H>0)){row["reason"]="actual_inward_dependent_direction_not_blocked";rows.push_back(row);continue;}
   const double before=x[5],outside=std::nextafter(before,block.lower[5]);bool boundary=outside<before&&!gates(outside);bool accepted=false;
   if(!boundary){const double candidate=std::max(block.lower[5],before-G/H);if(!(candidate<before)||gates(candidate)){row["reason"]="one_coordinate_conditional_optimum_is_interior";rows.push_back(row);continue;}double lo=candidate,hi=before;while(std::nextafter(lo,hi)<hi){const double mid=lo+(hi-lo)*.5;if(mid==lo||mid==hi)break;if(gates(mid))hi=mid;else lo=mid;}
    x[5]=hi;try{ready(b,true);const auto trial=actual(p,x,false,true);long double difference=0;if(trial.factor_cost.size()!=base.factor_cost.size())throw std::runtime_error("optical affected objective dimensions changed");for(std::size_t i=0;i<trial.factor_cost.size();++i)difference+=trial.factor_cost[i]-base.factor_cost[i];accepted=G*(hi-before)<0&&difference<0;row["actual_full_objective_difference"]=double(difference);row["dependent_before"]=before;row["dependent_proposed"]=hi;row["one_coordinate_descent_accepted"]=accepted;if(!accepted)x[5]=before;ready(b,true);}catch(...){x[5]=before;ready(b,true);throw;}
    if(!accepted){row["reason"]="true_complete_objective_did_not_decrease";rows.push_back(row);continue;}primal_changed=true;boundary=true;const auto reached=actual(p,x,true,false);const double reached_G=double(reached.gradient),reached_tol=128*std::numeric_limits<double>::epsilon()*std::max(1.,std::abs(reached_G));row["actual_JTr_at_accepted_boundary"]=reached_G;if(!(reached_G>reached_tol)){row["reason"]="accepted_boundary_has_true_inward_descent_released";rows.push_back(row);continue;}
   }
   std::array<double,2>g,out;gates(x[5],&g);gates(std::nextafter(x[5],block.lower[5]),&out);std::vector<int>faces;for(int e=0;e<2;++e)if(g[e]<=0&&out[e]>0)faces.push_back(e);if(faces.empty()){row["reason"]="dependent_box_not_an_optical_boundary";rows.push_back(row);continue;}if(faces.size()>1)throw std::runtime_error("multiple optical certificate faces became independently active; no one-face chart installed");const int endpoint=faces.front();auto map=std::make_unique<JointOpticalDomainFaceManifoldV1>(rig,range,block,original,endpoint,x);Held h;h.x=x;h.original=original;h.rig=&rig;h.face=map.get();for(int a=5;a<=10;++a){h.lo[a-5]=p.GetParameterLowerBound(x,a);h.hi[a-5]=p.GetParameterUpperBound(x,a);}held_.push_back(h);p.SetManifold(x,map.release());for(int a=5;a<=10;++a){p.SetParameterLowerBound(x,a,-std::numeric_limits<double>::max());p.SetParameterUpperBound(x,a,std::numeric_limits<double>::max());}signature.emplace(rig.id,endpoint);row["active"]=true;row["endpoint"]=endpoint;row["saved_original_g"]=h.face->level();row["outward_next_representable_k1_rejected"]=true;row["reason"]="actual_outward_dependent_gradient_at_true_boundary";rows.push_back(row);
  }}catch(...){restore(p);throw;}
  return {{"schema","rinkfit.original_closed_optical_working_set.v1"},{"rigs",rows},{"active_faces",held_.size()},{"accepted_original_objective_coordinate_step",primal_changed},{"original_certificate_threshold_unchanged",true},{"source_or_parameter_values_reinitialized",false},{"unrelated_factors_unchanged",true}};
 }
 template<class Builder>bool invalidated(Builder&b,ceres::Problem&p){if(held_.empty())return false;ready(b);for(const auto&h:held_){connected_.clear();p.GetResidualBlocksForParameterBlock(h.x,&connected_);const auto raw=actual(p,h.x,true,false);const double g=double(raw.gradient),tol=128*std::numeric_limits<double>::epsilon()*std::max(1.,std::abs(g));if(g< -tol)return true;}return false;}
};
